from calendar import isleap, monthrange
from datetime import date, datetime, timedelta


_WEEKDAYS = {
    "MO": 0, "TU": 1, "WE": 2, "TH": 3,
    "FR": 4, "SA": 5, "SU": 6,
}


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    """Expand a fixed-offset recurrence into a half-open UTC window."""
    freq = rule["freq"]
    interval = rule.get("interval", 1)

    if freq not in {"daily", "weekly", "monthly", "yearly"}:
        raise ValueError(f"Unknown frequency: {freq!r}")
    if interval < 1:
        raise ValueError("interval must be at least 1")
    if "count" in rule and "until" in rule:
        raise ValueError("count and until are mutually exclusive")
    if "by_month_day" in rule and "by_nth_weekday" in rule:
        raise ValueError(
            "by_month_day and by_nth_weekday are mutually exclusive"
        )

    # All datetime arithmetic below is naive, in local wall time.
    offset = timedelta(minutes=rule["utc_offset_minutes"])
    local_window_start = datetime.fromisoformat(window_start[:-1]) + offset
    local_window_end = datetime.fromisoformat(window_end[:-1]) + offset

    if local_window_start == local_window_end:
        return []

    start = datetime.fromisoformat(rule["start"])
    until = (
        datetime.fromisoformat(rule["until"])
        if "until" in rule else None
    )
    count = rule.get("count")

    # Count-limited rules must account for occurrences before the window.
    # Other rules can jump directly to its first relevant period.
    lower = start if count is not None else max(start, local_window_start)
    upper = min(local_window_end, until) if until is not None else local_window_end

    if lower > upper or lower >= local_window_end:
        return []

    excluded = {
        datetime.fromisoformat(value)
        for value in rule.get("exclude", [])
    }
    time_of_day = start.time()
    first_date = lower.date()
    last_date = upper.date()

    def first_active_period(distance: int) -> int:
        """Round a nonnegative period distance up to an interval multiple."""
        return ((distance + interval - 1) // interval) * interval

    def candidate_dates():
        if freq == "daily":
            origin = start.date().toordinal()
            first = origin + first_active_period(
                first_date.toordinal() - origin
            )
            for ordinal in range(first, last_date.toordinal() + 1, interval):
                yield date.fromordinal(ordinal)

        elif freq == "weekly":
            origin = start.date().toordinal() - start.weekday()
            weekdays = sorted({
                _WEEKDAYS[value]
                for value in rule.get(
                    "by_weekday",
                    [next(
                        name for name, number in _WEEKDAYS.items()
                        if number == start.weekday()
                    )],
                )
            })
            week_distance = (first_date.toordinal() - origin) // 7
            first_monday = origin + 7 * first_active_period(week_distance)

            for monday in range(
                first_monday, last_date.toordinal() + 1, 7 * interval
            ):
                for weekday in weekdays:
                    yield date.fromordinal(monday + weekday)

        elif freq == "monthly":
            origin = start.year * 12 + start.month - 1
            first_month = first_date.year * 12 + first_date.month - 1
            last_month = last_date.year * 12 + last_date.month - 1
            first = origin + first_active_period(first_month - origin)

            nth_weekday = rule.get("by_nth_weekday")
            month_days = rule.get("by_month_day", [start.day])

            for month_index in range(first, last_month + 1, interval):
                year, zero_based_month = divmod(month_index, 12)
                month = zero_based_month + 1
                first_weekday, length = monthrange(year, month)

                if nth_weekday is not None:
                    n, weekday_name = nth_weekday
                    weekday = _WEEKDAYS[weekday_name]

                    if n > 0:
                        day = (
                            1 + (weekday - first_weekday) % 7
                            + 7 * (n - 1)
                        )
                    else:
                        last_weekday = (first_weekday + length - 1) % 7
                        day = (
                            length - (last_weekday - weekday) % 7
                            + 7 * (n + 1)
                        )

                    if 1 <= day <= length:
                        yield date(year, month, day)
                else:
                    days = {
                        value if value > 0 else length + value + 1
                        for value in month_days
                    }
                    for day in sorted(days):
                        if 1 <= day <= length:
                            yield date(year, month, day)

        else:  # yearly
            first_year = start.year + first_active_period(
                first_date.year - start.year
            )
            for year in range(first_year, last_date.year + 1, interval):
                if start.month == 2 and start.day == 29 and not isleap(year):
                    continue
                yield date(year, start.month, start.day)

    result = []
    consumed = 0

    for occurrence_date in candidate_dates():
        occurrence = datetime.combine(occurrence_date, time_of_day)

        # The containing week/month/year may include dates before lower.
        if occurrence < lower:
            continue
        if occurrence >= local_window_end:
            break
        if until is not None and occurrence > until:
            break

        # Exclusions consume count; nonexistent dates never reach here.
        consumed += 1

        if occurrence >= local_window_start and occurrence not in excluded:
            utc_occurrence = occurrence - offset
            result.append(utc_occurrence.isoformat(timespec="minutes") + "Z")

        if count is not None and consumed >= count:
            break

    return result
